"""Compile explicit experimental harness sources into a fresh isolated classpath prefix."""
import argparse
import importlib.util
import json
import os
from pathlib import Path
import shutil

PHASE = Path(__file__).resolve().parent


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--classpath', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--source', type=Path, action='append', required=True)
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if not args.slot_granted:
        raise ValueError('Exclusive Java slot required')
    spec = importlib.util.spec_from_file_location('admission_contract_runner', PHASE / 'contracts/run_contracts.py')
    helper = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(helper)
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    shutil.copyfile(__file__, output / 'compiler-at-launch.py')
    cp_file = args.classpath.resolve(strict=True)
    cp = cp_file.read_text().strip()
    sources = []
    hashes = {}
    for source in args.source:
        source = source.resolve(strict=True)
        target = output / 'src' / source.name
        target.parent.mkdir(exist_ok=True)
        if target.exists():
            raise ValueError('Repeated source name')
        shutil.copyfile(source, target)
        sources.append(target)
        hashes[str(source)] = helper.digest(source)
    helper.write(output / 'inputs.json', {'classpath': str(cp_file), 'classpathSha256': helper.digest(cp_file),
                                         'sources': hashes})
    prefix = output / 'classes'
    prefix.mkdir()
    result = helper.run(output, 'compile', [helper.JAVA_HOME / 'bin/javac', '--release', '25', '-g', '-proc:none',
        '-implicit:none', '-sourcepath', '', '-encoding', 'UTF-8', '-cp', cp, '-d', prefix, *sources])
    if result['exitCode']:
        print((output / 'compile.log').read_text())
        raise RuntimeError('Experimental support compilation failed')
    classes = helper.tree(prefix)
    if not classes or any(not name.startswith('org/eclipse/rdf4j/sail/lmdb/') for name in classes):
        raise ValueError('Unexpected support namespace or empty output')
    (output / 'classpath.txt').write_text(str(prefix) + os.pathsep + cp + '\n')
    helper.write(output / 'class-files.json', classes)
    helper.write(output / 'compile-receipt.json', {'compiled': True, 'qualifiedForTiming': False,
        'sourceHashes': hashes, 'classFilesSha256': helper.digest(output / 'class-files.json'),
        'classpathSha256': helper.digest(output / 'classpath.txt')})
    print(json.dumps({'output': str(output), 'compiledClasses': len(classes)}))


if __name__ == '__main__':
    main()
